#!/usr/bin/env bash
# AKFC — Création d'utilisateur : plusieurs groupes au lieu d'un seul.
#  - formulaire : cases à cocher (groupe Administrateurs en tête, badge « Admin »), au moins un
#  - serveur (user.create) : groupIds[] (≥ 1, doublons ignorés, groupe inconnu refusé AVANT création)
#  Aucune migration. Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-user-create-multigroup.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
FILES=(packages/backend/src/modules/users/router.ts "apps/web/src/app/(admin)/dashboard/users/create/page.tsx" apps/web/src/features/admin/users/forms/CreateUserForm.tsx)
grep -q "groupIds: string\[\]" apps/web/src/features/admin/users/forms/CreateUserForm.tsx && { echo "— déjà appliqué"; exit 0; }
BK=/tmp/akfc_mg_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do [ -f "$f" ] || { echo "ERREUR: $f introuvable." >&2; exit 1; }; mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_mg; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== application =="
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(users): création d'un utilisateur dans plusieurs groupes

